  --card-bg: rgba(255, 255, 255, 0.98);
  --text-main: #4A4A4A;
  --text-sub: #888888;
  --accent-pink: #FFB7C5;
  --accent-blue: #A2D2FF;
  --border-soft: #F0F0F0;
