/* ⚠️HTML 的 id 必须与下方选择器一一对应，不得引用骨架中不存在的 id */
/* ⚠️此为通用示例，实际字段名/路径需替换为本卡 schema 的真实一级分类与字段 */
function populateCharacterData() {
  try {
    const all_variables = getAllVariables();
    const data = _.get(all_variables, "stat_data", {});

    // 示例1：数值型字段（带进度条）—— 替换 "一级分类.字段名" 为真实路径
