    const strVal = _.get(data, "一级分类.字段名", "-");
    $("#example-str-val").text(strVal);

    // 示例3：派生 $ 字段（zod transform 自动生成，AI 不更新）
    // const phase = _.get(data, "角色.$好感度阶段", "陌生");
    // $("#phase-val").text(phase);

    /* 刷新成功后触发动画 */
    const root = document.getElementById("render-root");
    if (root) {
      root.classList.add("flash-update");
      setTimeout(() => root.classList.remove("flash-update"), 300);
    }
  } catch (e) {
    console.warn("[statusbar] populateCharacterData 失败:", e.message);
  }
}


async function init() {
  /* 1. 等待 MVU 核心就绪 */
  await waitGlobalInitialized("Mvu");
  /* 2. 执行首次渲染 */
  populateCharacterData();
  /* 3. 监听变量更新结束事件，实现即时自动刷新（优于定时器） */
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => { populateCharacterData(); });
  /* 4. 绑定 UI 交互 */
  $(".status-header").on("click", function() { $("#render-root").slideToggle(200); });
}
/* 必须使用 errorCatched 包装以防止脚本崩溃导致酒馆卡死 */
$(errorCatched(init));
